```ts
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

/**
 * Fetches a user by their email address.
 * @param email - The email address to look up.
 * @returns The user's id, name, and email, or null if not found.
 */
export async function getUserByEmail(
  email: string
): Promise<{ id: string; name: string | null; email: string } | null> {
  const user = await prisma.user.findUnique({
    where: { email },
    select: {
      id: true,
      name: true,
      email: true,
    },
  });

  return user;
}
```

---

### Key decisions explained

| Detail | Reason |
|---|---|
| `findUnique` | `email` is typically a unique field, making this the most precise and efficient query. |
| `select` | Only fetches the three required fields (`id`, `name`, `email`) instead of the whole record — reduces data transfer and avoids leaking sensitive fields (e.g., `password`). |
| Return type `… \| null` | `findUnique` returns `null` when no record matches, so the return type is explicit about that possibility, forcing callers to handle it. |
| `name: string \| null` | Prisma models `name` as nullable by default unless your schema marks it `@required` — the type reflects that honestly. |
| Shared `PrismaClient` | In a real app, import a **singleton** instance rather than creating a new `PrismaClient` per call to avoid exhausting DB connections. |

### Example usage

```ts
const user = await getUserByEmail("alice@example.com");

if (!user) {
  console.log("No user found with that email.");
} else {
  console.log(`Found user: ${user.name} (${user.id})`);
}
```

