export async function connectAndFetchUser(id: number): Promise<string> {
  // Prisma reads DATABASE_URL from the environment automatically.
  // Passing the url explicitly here makes the dependency crystal-clear
  // and allows callers / tests to override it if needed.
  const prisma = new PrismaClient({
    datasources: {
      db: {
        url: process.env.DATABASE_URL,
      },
    },
  });

  try {
    await prisma.$connect();

    const user = await prisma.user.findUniqueOrThrow({
      where: { id },
      select: { email: true }, // fetch only what we need
    });

    return user.email;
  } finally {
    // Always disconnect, even if an error is thrown above
    await prisma.$disconnect();
  }
}
